insert into public.reviews (guest_name, origin, quote, tour_slug, position, published) values
  ('Sample guest', '{"en":"Melbourne, Australia","id":"Melbourne, Australia","fr":"Melbourne, Australie"}'::jsonb, '{"en":"Our driver picked us up at YIA after a late flight and had us at Borobudur before the crowds the next morning. Easy from start to finish.","id":"Sopir kami menjemput di YIA setelah penerbangan malam, dan besok paginya kami sudah di Borobudur sebelum ramai. Lancar dari awal sampai akhir.","fr":"Notre chauffeur nous a récupérés à YIA après un vol tardif et nous a emmenés à Borobudur avant la foule le lendemain matin. Simple du début à la fin."}'::jsonb, 'borobudur-prambanan', 0, true),
  ('Sample guest', '{"en":"Utrecht, the Netherlands","id":"Utrecht, Belanda","fr":"Utrecht, Pays-Bas"}'::jsonb, '{"en":"Two days to Bromo and back with a careful driver who knew every stop on the way. We could stop whenever we wanted.","id":"Dua hari PP ke Bromo dengan sopir yang hati-hati dan hafal setiap tempat singgah. Kami bisa berhenti kapan pun kami mau.","fr":"Deux jours aller-retour au Bromo avec un chauffeur prudent qui connaissait chaque arrêt sur la route. Nous pouvions nous arrêter quand nous voulions."}'::jsonb, 'bromo-madakaripura', 1, true),
  ('Sample guest', '{"en":"Lyon, France","id":"Lyon, Prancis","fr":"Lyon, France"}'::jsonb, '{"en":"We made our own plan for the day and the driver followed it without fuss, and found us a great place for lunch.","id":"Kami buat rencana sendiri untuk hari itu dan sopirnya mengikutinya tanpa repot, bahkan menemukan tempat makan siang yang enak.","fr":"Nous avons fait notre propre programme pour la journée, le chauffeur l''a suivi sans difficulté et nous a trouvé un excellent endroit pour déjeuner."}'::jsonb, 'jogja-beach-city', 2, true);
insert into public.faqs (question, answer, position, published) values
  ('{"en":"Is the price per person?","id":"Apakah harganya per orang?","fr":"Le prix est-il par personne ?"}'::jsonb, '{"en":"No. Every price is for the whole vehicle, with driver, fuel, parking and mineral water. An Avanza, Xenia or Innova takes up to 7 people, a HiAce up to 12.","id":"Tidak. Semua harga untuk satu kendaraan, sudah termasuk sopir, BBM, parkir, dan air mineral. Avanza, Xenia, atau Innova muat sampai 7 orang, HiAce sampai 12 orang.","fr":"Non. Chaque prix est pour le véhicule entier, avec chauffeur, carburant, parking et eau minérale. Une Avanza, Xenia ou Innova transporte jusqu''à 7 personnes, un HiAce jusqu''à 12."}'::jsonb, 0, true),
  ('{"en":"Are entrance tickets included?","id":"Apakah tiket masuk sudah termasuk?","fr":"Les billets d''entrée sont-ils inclus ?"}'::jsonb, '{"en":"No. Entrance tickets, jeeps, rafting and other activities are paid separately and can change with each site''s rules. We can help arrange them if you ask.","id":"Tidak. Tiket masuk, jip, rafting, dan aktivitas lain dibayar terpisah dan bisa berubah sesuai aturan tiap tempat wisata. Kami bisa bantu mengaturnya jika Anda minta.","fr":"Non. Les billets d''entrée, jeeps, rafting et autres activités se paient à part et peuvent changer selon les règles de chaque site. Nous pouvons vous aider à les organiser si vous le souhaitez."}'::jsonb, 1, true),
  ('{"en":"Can you pick us up from the airport?","id":"Bisakah kami dijemput di bandara?","fr":"Pouvez-vous venir nous chercher à l''aéroport ?"}'::jsonb, '{"en":"Yes, from Yogyakarta International Airport (YIA), 24 hours a day. Transfers to Jogja start from Rp 250,000 and depend on the distance.","id":"Bisa, dari Bandara Internasional Yogyakarta (YIA), 24 jam sehari. Transfer ke Jogja mulai dari Rp 250.000, tergantung jarak.","fr":"Oui, à l''aéroport international de Yogyakarta (YIA), 24 h/24. Les transferts vers Jogja commencent à Rp 250 000 et dépendent de la distance."}'::jsonb, 2, true),
  ('{"en":"Do we have to follow the package itinerary?","id":"Apakah kami harus mengikuti jadwal paket?","fr":"Faut-il suivre l''itinéraire du circuit ?"}'::jsonb, '{"en":"No. Choose your own stops and times, and your driver follows your plan. The packages are a starting point.","id":"Tidak. Pilih sendiri tujuan dan waktunya, sopir akan mengikuti rencana Anda. Paket hanya sebagai titik awal.","fr":"Non. Choisissez vos étapes et vos horaires, votre chauffeur suit votre programme. Les circuits sont un point de départ."}'::jsonb, 3, true),
  ('{"en":"Can you drive further than Jogja?","id":"Bisakah mengantar lebih jauh dari Jogja?","fr":"Pouvez-vous aller plus loin que Jogja ?"}'::jsonb, '{"en":"Yes. We drive to Bromo, Ijen, Tumpak Sewu, Dieng, Pangandaran, Karimunjawa and other places across Java, and on to Bali.","id":"Bisa. Kami melayani perjalanan ke Bromo, Ijen, Tumpak Sewu, Dieng, Pangandaran, Karimunjawa, dan tempat lain di seluruh Jawa, sampai ke Bali.","fr":"Oui. Nous allons au Bromo, à l''Ijen, à Tumpak Sewu, à Dieng, à Pangandaran, à Karimunjawa et ailleurs à Java, et jusqu''à Bali."}'::jsonb, 4, true),
  ('{"en":"What should we wear for the temples?","id":"Pakaian apa yang cocok untuk ke candi?","fr":"Comment s''habiller pour les temples ?"}'::jsonb, '{"en":"Light clothes that cover your shoulders and knees, and shoes you can walk in. For sunrise trips, bring a jacket: it''s cold before dawn.","id":"Pakaian ringan yang menutupi bahu dan lutut, serta sepatu yang nyaman untuk berjalan. Untuk perjalanan sunrise, bawa jaket karena udara dingin sebelum fajar.","fr":"Des vêtements légers qui couvrent les épaules et les genoux, et des chaussures confortables pour marcher. Pour les levers de soleil, prenez une veste : il fait froid avant l''aube."}'::jsonb, 5, true);
